<#
.SYNOPSIS
  RDP Session Audit GUI 1.2.3
  История RDP-сессий по выбранному периоду с реконструкцией жизненного цикла сеанса.

.DESCRIPTION
  Основной источник:
    Microsoft-Windows-TerminalServices-LocalSessionManager/Operational
      21 - logon
      23 - logoff
      24 - disconnect
      25 - reconnect
      39 - explicit disconnect / disconnect by another session (если доступно)
      40 - disconnect reason code (если доступно)

  Дополнительные источники:
    Microsoft-Windows-TerminalServices-RemoteConnectionManager/Operational
      1149 - successful RDP authentication

    Security
      4624 LogonType 10 - RemoteInteractive logon
      4634 - session terminated
      4647 - user initiated logoff
      4778 - RDP reconnect
      4779 - RDP disconnect

  Скрипт совместим с Windows PowerShell 4.0+ и рассчитан в том числе
  на Windows Server 2012 R2.

.NOTES
  ВАЖНО:
  - "DISCONNECT / session left open" означает, что пользователь НЕ сделал Log off.
    Это типичная картина при закрытии окна RDP крестиком, но тот же результат
    может дать потеря сети, аварийное закрытие клиента и т.п.
  - Поэтому программа достоверно отличает Log off от Disconnect, но не обещает
    со 100% точностью доказать, что конкретный Disconnect был именно кликом по X.
  - Если журналы очищены/перезаписаны, часть сеанса может быть помечена как PARTIAL.
#>

[CmdletBinding()]
param()

Set-StrictMode -Version 2.0
$ErrorActionPreference = 'Stop'
# NOTE: Ukrainian apostrophe in UI strings is U+02BC, not a PowerShell smart quote.

Add-Type -AssemblyName System.Windows.Forms
Add-Type -AssemblyName System.Drawing

# ---------------------------------------------------------------------------
# Global state
# ---------------------------------------------------------------------------

$script:Results = @()
$script:FilteredResults = @()
$script:LastStart = $null
$script:LastEnd = $null
$script:ComputerName = $env:COMPUTERNAME
$script:AppVersion = '1.3.2'

$script:OptionLookbackDays = 30
$script:OptionUseSecurity = $false


# ---------------------------------------------------------------------------
# Application icon (embedded ICO)
# ---------------------------------------------------------------------------

$script:AppIcon = $null

try {
    $iconBytes = [Convert]::FromBase64String('')
    $iconStream = New-Object System.IO.MemoryStream(,$iconBytes)
    $tempIcon = New-Object System.Drawing.Icon($iconStream)

    # Clone detaches the Icon from the stream so the stream can be disposed.
    $script:AppIcon = [System.Drawing.Icon]$tempIcon.Clone()

    $tempIcon.Dispose()
    $iconStream.Dispose()
}
catch {
    $script:AppIcon = $null
}


# ---------------------------------------------------------------------------
# Helpers
# ---------------------------------------------------------------------------

function Test-IsAdministrator {
    try {
        $identity = [Security.Principal.WindowsIdentity]::GetCurrent()
        $principal = New-Object Security.Principal.WindowsPrincipal($identity)
        return $principal.IsInRole([Security.Principal.WindowsBuiltInRole]::Administrator)
    }
    catch {
        return $false
    }
}

function Get-EventDataMap {
    param(
        [Parameter(Mandatory=$true)]
        [System.Diagnostics.Eventing.Reader.EventRecord]$Event
    )

    $map = @{}

    try {
        $xml = [xml]$Event.ToXml()

        if ($xml.Event.EventData -and $xml.Event.EventData.Data) {
            foreach ($d in $xml.Event.EventData.Data) {
                if ($null -ne $d.Name -and [string]$d.Name -ne '') {
                    $map[[string]$d.Name] = [string]$d.'#text'
                }
            }
        }
    }
    catch {}

    return $map
}

function Get-UserDataMap {
    param(
        [Parameter(Mandatory=$true)]
        [System.Diagnostics.Eventing.Reader.EventRecord]$Event
    )

    $map = @{}

    try {
        $xml = [xml]$Event.ToXml()

        if ($xml.Event.UserData) {
            $root = $xml.Event.UserData.ChildNodes | Select-Object -First 1

            if ($root) {
                foreach ($node in $root.ChildNodes) {
                    if ($node.LocalName) {
                        $map[[string]$node.LocalName] = [string]$node.InnerText
                    }
                }
            }
        }
    }
    catch {}

    return $map
}

function Get-FirstMapValue {
    param(
        [hashtable]$Map,
        [string[]]$Names
    )

    foreach ($name in $Names) {
        if ($Map.ContainsKey($name)) {
            $value = [string]$Map[$name]
            if (-not [string]::IsNullOrWhiteSpace($value)) {
                return $value
            }
        }
    }

    return $null
}

function Normalize-Address {
    param([string]$Address)

    if ([string]::IsNullOrWhiteSpace($Address)) {
        return ''
    }

    $a = $Address.Trim()

    if ($a -in @('-', 'LOCAL', '0.0.0.0', '::', '::1', '127.0.0.1')) {
        return ''
    }

    if ($a.StartsWith('::ffff:')) {
        return $a.Substring(7)
    }

    return $a
}

function Split-Principal {
    param(
        [string]$Principal,
        [string]$FallbackDomain = ''
    )

    $domain = ''
    $user = ''

    if ([string]::IsNullOrWhiteSpace($Principal)) {
        return [pscustomobject]@{
            Account = ''
            Domain = ''
            UserName = ''
            Scope = 'Unknown'
        }
    }

    $p = $Principal.Trim()

    if ($p.Contains('\')) {
        $parts = $p.Split('\', 2)
        $domain = $parts[0]
        $user = $parts[1]
    }
    elseif ($p.Contains('@')) {
        $parts = $p.Split('@', 2)
        $user = $parts[0]
        $domain = $parts[1]
    }
    else {
        $user = $p
        $domain = $FallbackDomain
    }

    $scope = 'Unknown'

    if ([string]::IsNullOrWhiteSpace($domain)) {
        $scope = 'Local/Unknown'
    }
    elseif (
        $domain -eq '.' -or
        $domain -eq $env:COMPUTERNAME -or
        $domain -eq 'WORKGROUP'
    ) {
        $scope = 'Local'
    }
    else {
        $scope = 'Domain'
    }

    $account = $user

    if (-not [string]::IsNullOrWhiteSpace($domain)) {
        $account = "$domain\$user"
    }

    return [pscustomobject]@{
        Account = $account
        Domain = $domain
        UserName = $user
        Scope = $scope
    }
}

function Get-ShortUserName {
    param([string]$Principal)

    $p = Split-Principal -Principal $Principal
    return $p.UserName.ToLowerInvariant()
}

function Add-UniqueString {
    param(
        [System.Collections.ArrayList]$List,
        [string]$Value
    )

    if ([string]::IsNullOrWhiteSpace($Value)) {
        return
    }

    if (-not $List.Contains($Value)) {
        [void]$List.Add($Value)
    }
}

function Format-Duration {
    param($Duration)

    if ($null -eq $Duration) {
        return ''
    }

    # In Windows PowerShell (including 4.0/5.1), Nullable[TimeSpan] is boxed
    # as a plain TimeSpan when it has a value, so .Value does not exist.
    try {
        $ts = [TimeSpan]$Duration
    }
    catch {
        return ''
    }

    if ($ts.TotalSeconds -lt 0) {
        return ''
    }

    $days = [math]::Floor($ts.TotalDays)

    if ($days -gt 0) {
        return ('{0}d {1:00}:{2:00}:{3:00}' -f $days, $ts.Hours, $ts.Minutes, $ts.Seconds)
    }

    return ('{0:00}:{1:00}:{2:00}' -f $ts.Hours, $ts.Minutes, $ts.Seconds)
}

function Get-Reason40Label {
    param([string]$Reason)

    if ([string]::IsNullOrWhiteSpace($Reason)) {
        return ''
    }

    switch ($Reason) {
        '0'  { return '0: no additional info / client connection ended' }
        '5'  { return '5: connection replaced by another connection' }
        '11' { return '11: user initiated disconnect' }
        default {
            $hex = ''
            try {
                $n = [uint32]$Reason
                $hex = ('0x{0:X8}' -f $n)
            }
            catch {}

            if ($hex) {
                return "$Reason ($hex)"
            }

            return $Reason
        }
    }
}

function Get-SafeWinEvents {
    param(
        [string]$LogName,
        [int[]]$Ids,
        [datetime]$Start,
        [datetime]$End
    )

    try {
        $logInfo = Get-WinEvent -ListLog $LogName -ErrorAction Stop

        if (-not $logInfo.IsEnabled) {
            return @()
        }

        $filter = @{
            LogName = $LogName
            Id = $Ids
            StartTime = $Start
            EndTime = $End
        }

        return @(Get-WinEvent -FilterHashtable $filter -ErrorAction Stop)
    }
    catch {
        return @()
    }
}

function New-InternalSession {
    param(
        [string]$Principal,
        [string]$FallbackDomain,
        [string]$SessionId,
        [Nullable[datetime]]$StartTime,
        [datetime]$ObservedStart,
        [bool]$PartialStart,
        [string]$Source
    )

    $p = Split-Principal -Principal $Principal -FallbackDomain $FallbackDomain

    return [pscustomobject]@{
        Account = $p.Account
        Domain = $p.Domain
        UserName = $p.UserName
        Scope = $p.Scope

        SessionId = [string]$SessionId

        StartTime = $StartTime
        ObservedStart = $ObservedStart
        EndTime = $null

        PartialStart = $PartialStart
        PartialEnd = $false

        State = 'Active'
        Closure = 'Open'
        ClosureDetail = ''

        ConnectedSince = $ObservedStart
        ConnectedTicks = [int64]0

        DisconnectCount = 0
        ReconnectCount = 0
        ExplicitDisconnectCount = 0
        DisconnectedByOther = $false

        LastDisconnectReason = ''
        LastDisconnectTime = $null

        IPs = New-Object System.Collections.ArrayList
        Clients = New-Object System.Collections.ArrayList
        AuthPackages = New-Object System.Collections.ArrayList
        LogonIds = New-Object System.Collections.ArrayList

        LastIP = ''
        LastClient = ''

        Source = $Source
        FirstEventTime = $ObservedStart
        LastEventTime = $ObservedStart

        EventIds = New-Object System.Collections.ArrayList
    }
}

function Add-ConnectedTime {
    param(
        $Session,
        [datetime]$Until
    )

    if ($null -ne $Session.ConnectedSince) {
        $delta = $Until - [datetime]$Session.ConnectedSince

        if ($delta.Ticks -gt 0) {
            $Session.ConnectedTicks += $delta.Ticks
        }

        $Session.ConnectedSince = $null
    }
}

function New-NearEventIndex {
    param(
        [object[]]$Events,
        [switch]$IncludeKind
    )

    $index = @{}

    foreach ($e in @($Events)) {
        if ($null -eq $e) {
            continue
        }

        $user = [string]$e.ShortUser

        if ([string]::IsNullOrWhiteSpace($user)) {
            continue
        }

        $minute = ([datetime]$e.TimeCreated).ToString('yyyyMMddHHmm')
        $kind = ''

        if ($IncludeKind -and $e.PSObject.Properties['Kind']) {
            $kind = [string]$e.Kind
        }

        $key = if ($IncludeKind) {
            "$kind|$user|$minute"
        }
        else {
            "$user|$minute"
        }

        if (-not $index.ContainsKey($key)) {
            $index[$key] = New-Object System.Collections.ArrayList
        }

        [void]$index[$key].Add($e)
    }

    return $index
}

function Get-NearIndexedEvent {
    param(
        [hashtable]$Index,
        [string]$UserName,
        [datetime]$Time,
        [string]$Kind = '',
        [int]$Seconds = 15
    )

    if ($null -eq $Index -or [string]::IsNullOrWhiteSpace($UserName)) {
        return $null
    }

    $user = $UserName.ToLowerInvariant()
    $min = $Time.AddSeconds(-1 * $Seconds)
    $max = $Time.AddSeconds($Seconds)
    $best = $null
    $bestDistance = [double]::MaxValue

    # +/- one minute is enough for the 15-second correlation window,
    # including events around a minute boundary.
    foreach ($offset in @(-1,0,1)) {
        $probe = $Time.AddMinutes($offset)
        $minute = $probe.ToString('yyyyMMddHHmm')

        $key = if ([string]::IsNullOrWhiteSpace($Kind)) {
            "$user|$minute"
        }
        else {
            "$Kind|$user|$minute"
        }

        if (-not $Index.ContainsKey($key)) {
            continue
        }

        foreach ($candidate in $Index[$key]) {
            $ct = [datetime]$candidate.TimeCreated

            if ($ct -lt $min -or $ct -gt $max) {
                continue
            }

            $distance = [math]::Abs(($ct - $Time).TotalMilliseconds)

            if ($distance -lt $bestDistance) {
                $best = $candidate
                $bestDistance = $distance
            }
        }
    }

    return $best
}

# ---------------------------------------------------------------------------
# Parse enrichment logs
# ---------------------------------------------------------------------------

function Get-RcmAuthEvents {
    param(
        [datetime]$Start,
        [datetime]$End
    )

    $log = 'Microsoft-Windows-TerminalServices-RemoteConnectionManager/Operational'
    $events = Get-SafeWinEvents -LogName $log -Ids @(1149) -Start $Start -End $End
    $out = New-Object System.Collections.ArrayList

    foreach ($ev in $events) {
        $m = Get-UserDataMap -Event $ev

        $user = Get-FirstMapValue -Map $m -Names @('Param1','User','UserName')
        $domain = Get-FirstMapValue -Map $m -Names @('Param2','Domain')
        $address = Normalize-Address (Get-FirstMapValue -Map $m -Names @('Param3','Address','ClientAddress'))

        if ([string]::IsNullOrWhiteSpace($user)) {
            continue
        }

        $principal = $user

        if ($domain -and -not $user.Contains('\') -and -not $user.Contains('@')) {
            $principal = "$domain\$user"
        }

        $p = Split-Principal -Principal $principal

        [void]$out.Add([pscustomobject]@{
            TimeCreated = $ev.TimeCreated
            Principal = $p.Account
            Domain = $p.Domain
            UserName = $p.UserName
            ShortUser = $p.UserName.ToLowerInvariant()
            Address = $address
            Source = 'RCM 1149'
        })
    }

    return @($out | Sort-Object TimeCreated)
}

function Get-SecurityRdpEvents {
    param(
        [datetime]$Start,
        [datetime]$End
    )

    $events = Get-SafeWinEvents -LogName 'Security' -Ids @(4624,4634,4647,4778,4779) -Start $Start -End $End
    $parsed = New-Object System.Collections.ArrayList

    foreach ($ev in $events) {
        $d = Get-EventDataMap -Event $ev

        if ($ev.Id -eq 4624) {
            if ($d['LogonType'] -ne '10') {
                continue
            }

            $user = [string]$d['TargetUserName']

            if ([string]::IsNullOrWhiteSpace($user)) {
                continue
            }

            if ($user.EndsWith('$')) {
                continue
            }

            if ($user -in @('SYSTEM','LOCAL SERVICE','NETWORK SERVICE','ANONYMOUS LOGON')) {
                continue
            }

            $domain = [string]$d['TargetDomainName']
            $principal = if ($domain) { "$domain\$user" } else { $user }
            $p = Split-Principal -Principal $principal

            [void]$parsed.Add([pscustomobject]@{
                TimeCreated = $ev.TimeCreated
                EventId = 4624
                Principal = $p.Account
                Domain = $p.Domain
                UserName = $p.UserName
                ShortUser = $p.UserName.ToLowerInvariant()
                LogonId = [string]$d['TargetLogonId']
                Address = Normalize-Address ([string]$d['IpAddress'])
                Client = [string]$d['WorkstationName']
                AuthPackage = [string]$d['AuthenticationPackageName']
                Kind = 'LOGON'
            })
        }
        elseif ($ev.Id -eq 4634) {
            $logonId = [string]$d['TargetLogonId']

            if ([string]::IsNullOrWhiteSpace($logonId)) {
                $logonId = [string]$d['SubjectLogonId']
            }

            [void]$parsed.Add([pscustomobject]@{
                TimeCreated = $ev.TimeCreated
                EventId = 4634
                Principal = ''
                Domain = ''
                UserName = ''
                ShortUser = ''
                LogonId = $logonId
                Address = ''
                Client = ''
                AuthPackage = ''
                Kind = 'TERMINATED'
            })
        }
        elseif ($ev.Id -eq 4647) {
            $user = [string]$d['SubjectUserName']
            $domain = [string]$d['SubjectDomainName']
            $principal = if ($domain) { "$domain\$user" } else { $user }
            $p = Split-Principal -Principal $principal

            [void]$parsed.Add([pscustomobject]@{
                TimeCreated = $ev.TimeCreated
                EventId = 4647
                Principal = $p.Account
                Domain = $p.Domain
                UserName = $p.UserName
                ShortUser = $p.UserName.ToLowerInvariant()
                LogonId = [string]$d['SubjectLogonId']
                Address = ''
                Client = ''
                AuthPackage = ''
                Kind = 'USER_LOGOFF'
            })
        }
        elseif ($ev.Id -in @(4778,4779)) {
            $user = [string]$d['AccountName']
            $domain = [string]$d['AccountDomain']

            if ([string]::IsNullOrWhiteSpace($user)) {
                continue
            }

            $principal = if ($domain) { "$domain\$user" } else { $user }
            $p = Split-Principal -Principal $principal

            [void]$parsed.Add([pscustomobject]@{
                TimeCreated = $ev.TimeCreated
                EventId = $ev.Id
                Principal = $p.Account
                Domain = $p.Domain
                UserName = $p.UserName
                ShortUser = $p.UserName.ToLowerInvariant()
                LogonId = ''
                Address = Normalize-Address ([string]$d['ClientAddress'])
                Client = [string]$d['ClientName']
                AuthPackage = ''
                Kind = if ($ev.Id -eq 4778) { 'RECONNECT' } else { 'DISCONNECT' }
            })
        }
    }

    return @($parsed | Sort-Object TimeCreated)
}

# ---------------------------------------------------------------------------
# Security-only fallback sessions
# ---------------------------------------------------------------------------

function Get-SecurityFallbackSessions {
    param(
        [object[]]$SecurityEvents,
        [datetime]$RangeEnd
    )

    $byLogon = @{}
    $out = New-Object System.Collections.ArrayList

    foreach ($ev in ($SecurityEvents | Sort-Object TimeCreated)) {
        if ($ev.Kind -eq 'LOGON') {
            if ([string]::IsNullOrWhiteSpace($ev.LogonId)) {
                continue
            }

            $s = New-InternalSession `
                -Principal $ev.Principal `
                -FallbackDomain $ev.Domain `
                -SessionId '' `
                -StartTime $ev.TimeCreated `
                -ObservedStart $ev.TimeCreated `
                -PartialStart $false `
                -Source 'Security fallback'

            Add-UniqueString -List $s.IPs -Value $ev.Address
            Add-UniqueString -List $s.Clients -Value $ev.Client
            Add-UniqueString -List $s.AuthPackages -Value $ev.AuthPackage
            Add-UniqueString -List $s.LogonIds -Value $ev.LogonId

            $s.LastIP = $ev.Address
            $s.LastClient = $ev.Client
            [void]$s.EventIds.Add('4624')

            $byLogon[$ev.LogonId] = $s
        }
        elseif ($ev.Kind -eq 'USER_LOGOFF') {
            if ($byLogon.ContainsKey($ev.LogonId)) {
                $s = $byLogon[$ev.LogonId]
                $s.Closure = 'LOGOFF (proper)'
                $s.ClosureDetail = 'Security 4647: user initiated logoff'
                [void]$s.EventIds.Add('4647')
            }
        }
        elseif ($ev.Kind -eq 'TERMINATED') {
            if ($byLogon.ContainsKey($ev.LogonId)) {
                $s = $byLogon[$ev.LogonId]

                Add-ConnectedTime -Session $s -Until $ev.TimeCreated

                $s.EndTime = $ev.TimeCreated
                $s.LastEventTime = $ev.TimeCreated
                $s.State = 'Logged off'

                if ($s.Closure -ne 'LOGOFF (proper)') {
                    $s.Closure = 'TERMINATED (cause unknown)'
                    $s.ClosureDetail = 'Security 4634 without matching 4647'
                }

                [void]$s.EventIds.Add('4634')
                [void]$out.Add($s)
                $byLogon.Remove($ev.LogonId)
            }
        }
    }

    foreach ($key in @($byLogon.Keys)) {
        $s = $byLogon[$key]

        if ($null -ne $s.ConnectedSince) {
            Add-ConnectedTime -Session $s -Until $RangeEnd
            $s.ConnectedSince = $RangeEnd
        }

        $s.PartialEnd = $true
        $s.State = 'Open / unknown'
        $s.Closure = 'OPEN / no logoff event'
        [void]$out.Add($s)
    }

    return @($out)
}

# ---------------------------------------------------------------------------
# Primary LSM reconstruction
# ---------------------------------------------------------------------------

function Get-LsmSessions {
    param(
        [datetime]$QueryStart,
        [datetime]$RangeStart,
        [datetime]$RangeEnd,
        [object[]]$RcmEvents,
        [object[]]$SecurityEvents
    )

    $log = 'Microsoft-Windows-TerminalServices-LocalSessionManager/Operational'
    $events = Get-SafeWinEvents -LogName $log -Ids @(21,23,24,25,39,40) -Start $QueryStart -End $RangeEnd

    # Build correlation indexes once. Previous versions scanned the complete
    # RCM/Security arrays for every LSM event, which became very slow on large logs.
    $rcmIndex = New-NearEventIndex -Events $RcmEvents
    $securityIndex = New-NearEventIndex -Events $SecurityEvents -IncludeKind

    $open = @{}
    $closed = New-Object System.Collections.ArrayList

    foreach ($ev in ($events | Sort-Object TimeCreated)) {
        $m = Get-UserDataMap -Event $ev

        $principal = Get-FirstMapValue -Map $m -Names @('User','UserName','AccountName')
        $sessionId = Get-FirstMapValue -Map $m -Names @('SessionID','SessionId','Session','TargetSession')
        $address = Normalize-Address (Get-FirstMapValue -Map $m -Names @('Address','ClientAddress','SourceNetworkAddress'))

        if ($ev.Id -eq 39) {
            $target = Get-FirstMapValue -Map $m -Names @('TargetSession','Session','SessionID')
            $source = Get-FirstMapValue -Map $m -Names @('SourceSession')

            if ($target -and $open.ContainsKey([string]$target)) {
                $s = $open[[string]$target]
                $s.ExplicitDisconnectCount++
                $s.ClosureDetail = 'LSM 39: explicit disconnect'

                if ($source -and $source -ne $target) {
                    $s.DisconnectedByOther = $true
                    $s.ClosureDetail = "LSM 39: disconnected by another session ($source)"
                }

                $s.LastEventTime = $ev.TimeCreated
                [void]$s.EventIds.Add('39')
            }

            continue
        }

        if ($ev.Id -eq 40) {
            $sid40 = Get-FirstMapValue -Map $m -Names @('Session','SessionID','SessionId')
            $reason = Get-FirstMapValue -Map $m -Names @('Reason','ReasonCode')

            if ($sid40 -and $open.ContainsKey([string]$sid40)) {
                $s = $open[[string]$sid40]
                $s.LastDisconnectReason = Get-Reason40Label -Reason $reason
                $s.LastEventTime = $ev.TimeCreated
                [void]$s.EventIds.Add('40')
            }

            continue
        }

        if ([string]::IsNullOrWhiteSpace($sessionId)) {
            continue
        }

        $sid = [string]$sessionId

        # Enrichment by near RCM/Security event
        $pTemp = Split-Principal -Principal $principal
        $shortUser = $pTemp.UserName

        $nearRcm = $null
        $nearSec = $null
        $near477x = $null

        if ($shortUser) {
            if ($ev.Id -in @(21,25)) {
                $nearRcm = Get-NearIndexedEvent `
                    -Index $rcmIndex `
                    -UserName $shortUser `
                    -Time $ev.TimeCreated `
                    -Seconds 15

                $nearSec = Get-NearIndexedEvent `
                    -Index $securityIndex `
                    -UserName $shortUser `
                    -Time $ev.TimeCreated `
                    -Kind 'LOGON' `
                    -Seconds 15
            }

            if ($ev.Id -in @(24,25)) {
                $kind = if ($ev.Id -eq 24) { 'DISCONNECT' } else { 'RECONNECT' }

                $near477x = Get-NearIndexedEvent `
                    -Index $securityIndex `
                    -UserName $shortUser `
                    -Time $ev.TimeCreated `
                    -Kind $kind `
                    -Seconds 15
            }
        }

        if ([string]::IsNullOrWhiteSpace($principal)) {
            if ($nearRcm) {
                $principal = $nearRcm.Principal
            }
            elseif ($nearSec) {
                $principal = $nearSec.Principal
            }
            elseif ($open.ContainsKey($sid)) {
                $principal = $open[$sid].Account
            }
        }

        if (-not $address) {
            if ($nearRcm -and $nearRcm.Address) {
                $address = $nearRcm.Address
            }
            elseif ($nearSec -and $nearSec.Address) {
                $address = $nearSec.Address
            }
            elseif ($near477x -and $near477x.Address) {
                $address = $near477x.Address
            }
        }

        if ($ev.Id -eq 21) {
            # New logical session. If the ID is still occupied, previous lifecycle is incomplete.
            if ($open.ContainsKey($sid)) {
                $old = $open[$sid]
                Add-ConnectedTime -Session $old -Until $ev.TimeCreated
                $old.EndTime = $ev.TimeCreated
                $old.PartialEnd = $true
                $old.State = 'Closed by new session ID'
                $old.Closure = 'INCOMPLETE / SessionId reused'
                $old.ClosureDetail = 'New LSM 21 appeared with the same SessionId before a visible LSM 23'
                [void]$closed.Add($old)
                $open.Remove($sid)
            }

            $s = New-InternalSession `
                -Principal $principal `
                -FallbackDomain '' `
                -SessionId $sid `
                -StartTime $ev.TimeCreated `
                -ObservedStart $ev.TimeCreated `
                -PartialStart $false `
                -Source 'LSM'

            Add-UniqueString -List $s.IPs -Value $address
            $s.LastIP = $address
            [void]$s.EventIds.Add('21')

            if ($nearSec) {
                Add-UniqueString -List $s.Clients -Value $nearSec.Client
                Add-UniqueString -List $s.AuthPackages -Value $nearSec.AuthPackage
                Add-UniqueString -List $s.LogonIds -Value $nearSec.LogonId
                $s.LastClient = $nearSec.Client
            }

            if ($near477x) {
                Add-UniqueString -List $s.Clients -Value $near477x.Client
                $s.LastClient = $near477x.Client
            }

            $open[$sid] = $s
        }
        elseif ($ev.Id -eq 25) {
            if (-not $open.ContainsKey($sid)) {
                $s = New-InternalSession `
                    -Principal $principal `
                    -FallbackDomain '' `
                    -SessionId $sid `
                    -StartTime $null `
                    -ObservedStart $ev.TimeCreated `
                    -PartialStart $true `
                    -Source 'LSM partial'

                $s.ConnectedSince = $ev.TimeCreated
                $open[$sid] = $s
            }

            $s = $open[$sid]

            if (-not [string]::IsNullOrWhiteSpace($principal) -and [string]::IsNullOrWhiteSpace($s.UserName)) {
                $p = Split-Principal -Principal $principal
                $s.Account = $p.Account
                $s.Domain = $p.Domain
                $s.UserName = $p.UserName
                $s.Scope = $p.Scope
            }

            if ($null -eq $s.ConnectedSince) {
                $s.ConnectedSince = $ev.TimeCreated
            }

            $s.State = 'Active'
            $s.ReconnectCount++
            $s.LastEventTime = $ev.TimeCreated

            Add-UniqueString -List $s.IPs -Value $address
            $s.LastIP = $address

            if ($near477x) {
                Add-UniqueString -List $s.Clients -Value $near477x.Client
                $s.LastClient = $near477x.Client
            }

            if ($nearSec) {
                Add-UniqueString -List $s.Clients -Value $nearSec.Client
                Add-UniqueString -List $s.AuthPackages -Value $nearSec.AuthPackage
                Add-UniqueString -List $s.LogonIds -Value $nearSec.LogonId
                $s.LastClient = $nearSec.Client
            }

            [void]$s.EventIds.Add('25')
        }
        elseif ($ev.Id -eq 24) {
            if (-not $open.ContainsKey($sid)) {
                $s = New-InternalSession `
                    -Principal $principal `
                    -FallbackDomain '' `
                    -SessionId $sid `
                    -StartTime $null `
                    -ObservedStart $ev.TimeCreated `
                    -PartialStart $true `
                    -Source 'LSM partial'

                # We observed a disconnect, therefore connected time before this point is unknown.
                $s.ConnectedSince = $null
                $open[$sid] = $s
            }

            $s = $open[$sid]
            Add-ConnectedTime -Session $s -Until $ev.TimeCreated

            $s.State = 'Disconnected'
            $s.DisconnectCount++
            $s.LastDisconnectTime = $ev.TimeCreated
            $s.LastEventTime = $ev.TimeCreated

            Add-UniqueString -List $s.IPs -Value $address
            $s.LastIP = $address

            if ($near477x) {
                Add-UniqueString -List $s.Clients -Value $near477x.Client
                $s.LastClient = $near477x.Client
            }

            [void]$s.EventIds.Add('24')
        }
        elseif ($ev.Id -eq 23) {
            if (-not $open.ContainsKey($sid)) {
                $s = New-InternalSession `
                    -Principal $principal `
                    -FallbackDomain '' `
                    -SessionId $sid `
                    -StartTime $null `
                    -ObservedStart $ev.TimeCreated `
                    -PartialStart $true `
                    -Source 'LSM partial'

                $s.ConnectedSince = $null
                $open[$sid] = $s
            }

            $s = $open[$sid]
            Add-ConnectedTime -Session $s -Until $ev.TimeCreated

            $s.EndTime = $ev.TimeCreated
            $s.State = 'Logged off'
            $s.Closure = 'LOGOFF (proper)'
            $s.ClosureDetail = 'LSM 23: session logoff succeeded'
            $s.LastEventTime = $ev.TimeCreated
            [void]$s.EventIds.Add('23')

            [void]$closed.Add($s)
            $open.Remove($sid)
        }
    }

    # Sessions still alive at the selected End time
    foreach ($sid in @($open.Keys)) {
        $s = $open[$sid]

        if ($s.State -eq 'Active') {
            if ($null -ne $s.ConnectedSince) {
                Add-ConnectedTime -Session $s -Until $RangeEnd
                $s.ConnectedSince = $RangeEnd
            }

            $s.PartialEnd = $true
            $s.Closure = 'ACTIVE / still open'
            $s.ClosureDetail = 'No logoff/disconnect before selected End'
        }
        elseif ($s.State -eq 'Disconnected') {
            $s.PartialEnd = $true
            $s.Closure = 'DISCONNECT / session left open'

            if ($s.DisconnectedByOther) {
                $s.ClosureDetail = 'Disconnected by another session/admin'
            }
            elseif ($s.ExplicitDisconnectCount -gt 0) {
                $s.ClosureDetail = 'Explicit Disconnect was recorded (LSM 39)'
            }
            elseif ($s.LastDisconnectReason) {
                $s.ClosureDetail = $s.LastDisconnectReason
            }
            else {
                $s.ClosureDetail = 'Disconnected without Log off; X/network loss/client close cannot be distinguished reliably'
            }
        }

        [void]$closed.Add($s)
    }

    return @($closed)
}

# ---------------------------------------------------------------------------
# Merge / presentation
# ---------------------------------------------------------------------------

function Convert-SessionToResult {
    param(
        $Session,
        [datetime]$RangeStart,
        [datetime]$RangeEnd
    )

    $effectiveStart = $Session.StartTime
    if ($null -eq $effectiveStart) {
        $effectiveStart = $Session.ObservedStart
    }

    $effectiveEnd = $Session.EndTime
    if ($null -eq $effectiveEnd) {
        $effectiveEnd = $RangeEnd
    }

    $lifetime = $null
    if ($effectiveStart -and $effectiveEnd -and $effectiveEnd -ge $effectiveStart) {
        $lifetime = $effectiveEnd - $effectiveStart
    }

    $connected = [TimeSpan]::FromTicks([int64]$Session.ConnectedTicks)

    $disconnectSpan = $null
    if ($lifetime -and $connected -and $lifetime.Ticks -ge $connected.Ticks) {
        $disconnectSpan = $lifetime - $connected
    }

    $startDisplay = ''
    if ($Session.StartTime) {
        $startDisplay = ([datetime]$Session.StartTime).ToString('dd.MM.yyyy HH:mm:ss')
    }
    else {
        $startDisplay = 'before available history'
    }

    $endDisplay = ''
    if ($Session.EndTime) {
        $endDisplay = ([datetime]$Session.EndTime).ToString('dd.MM.yyyy HH:mm:ss')
    }

    $ips = @($Session.IPs | Where-Object { $_ } | Sort-Object -Unique)
    $clients = @($Session.Clients | Where-Object { $_ } | Sort-Object -Unique)
    $auth = @($Session.AuthPackages | Where-Object { $_ } | Sort-Object -Unique)
    $logonIds = @($Session.LogonIds | Where-Object { $_ } | Sort-Object -Unique)

    $quality = 'Complete'
    if ($Session.PartialStart -and $Session.PartialEnd) {
        $quality = 'Partial start + end'
    }
    elseif ($Session.PartialStart) {
        $quality = 'Partial start'
    }
    elseif ($Session.PartialEnd) {
        $quality = 'Open at range end'
    }

    $category = 'Other'
    if ($Session.Closure -eq 'LOGOFF (proper)') {
        $category = 'Proper logoff'
    }
    elseif ($Session.Closure -like 'DISCONNECT*') {
        $category = 'Disconnected/open'
    }
    elseif ($Session.Closure -like 'ACTIVE*') {
        $category = 'Active/open'
    }
    elseif ($Session.Closure -like 'INCOMPLETE*' -or $Session.Closure -like 'TERMINATED*' -or $Session.Closure -like 'OPEN*') {
        $category = 'Incomplete/unknown'
    }

    return [pscustomobject]@{
        Account = $Session.Account
        Scope = $Session.Scope
        SessionId = $Session.SessionId
        Started = $startDisplay
        Ended = $endDisplay
        Lifetime = if ($Session.PartialStart -and $lifetime) {
            '>= ' + (Format-Duration -Duration $lifetime)
        }
        else {
            Format-Duration -Duration $lifetime
        }
        ConnectedTime = Format-Duration -Duration $connected
        DisconnectedTime = Format-Duration -Duration $disconnectSpan
        FinalState = $Session.State
        Closure = $Session.Closure
        ClosureDetail = $Session.ClosureDetail
        Disconnects = $Session.DisconnectCount
        Reconnects = $Session.ReconnectCount
        IPs = ($ips -join '; ')
        LastIP = $Session.LastIP
        ClientNames = ($clients -join '; ')
        Auth = ($auth -join '; ')
        LogonIds = ($logonIds -join '; ')
        DataQuality = $quality
        Source = $Session.Source
        Events = (@($Session.EventIds | Sort-Object -Unique) -join ',')
        Category = $category

        _Start = $effectiveStart
        _End = $effectiveEnd
        _UserName = $Session.UserName
    }
}

function Test-SessionIntersectsRange {
    param(
        $Session,
        [datetime]$RangeStart,
        [datetime]$RangeEnd
    )

    $start = $Session.StartTime

    if ($null -eq $start) {
        $start = $Session.ObservedStart
    }

    $end = $Session.EndTime

    if ($null -eq $end) {
        $end = $RangeEnd
    }

    if ($end -lt $RangeStart) {
        return $false
    }

    if ($start -gt $RangeEnd) {
        return $false
    }

    return $true
}

function Merge-SecurityFallback {
    param(
        [object[]]$Primary,
        [object[]]$Fallback
    )

    $out = New-Object System.Collections.ArrayList

    foreach ($p in $Primary) {
        [void]$out.Add($p)
    }

    foreach ($f in $Fallback) {
        $fShort = $f.UserName.ToLowerInvariant()
        $fStart = $f.StartTime

        if ($null -eq $fStart) {
            $fStart = $f.ObservedStart
        }

        $match = $Primary |
            Where-Object {
                $_.UserName.ToLowerInvariant() -eq $fShort -and
                $_.StartTime -and
                [math]::Abs((([datetime]$_.StartTime) - ([datetime]$fStart)).TotalSeconds) -le 20
            } |
            Select-Object -First 1

        if ($match) {
            foreach ($ip in $f.IPs) {
                Add-UniqueString -List $match.IPs -Value $ip
            }

            foreach ($client in $f.Clients) {
                Add-UniqueString -List $match.Clients -Value $client
            }

            foreach ($auth in $f.AuthPackages) {
                Add-UniqueString -List $match.AuthPackages -Value $auth
            }

            foreach ($logonId in $f.LogonIds) {
                Add-UniqueString -List $match.LogonIds -Value $logonId
            }
        }
        else {
            [void]$out.Add($f)
        }
    }

    return @($out)
}

function Invoke-RdpAudit {
    param(
        [datetime]$Start,
        [datetime]$End,
        [int]$LookbackDays,
        [bool]$UseSecurity = $false
    )

    if ($End -le $Start) {
        throw 'End must be later than Start.'
    }

    $queryStart = $Start.AddDays(-1 * $LookbackDays)

    # Fast path:
    # LSM + RCM are enough for user / source IP / session lifecycle /
    # disconnect vs logoff / duration. Security is enormous on busy servers,
    # so we do not parse it unless the user explicitly requests enrichment.
    $rcm = Get-RcmAuthEvents -Start $queryStart -End $End
    $security = @()

    if ($UseSecurity) {
        $security = Get-SecurityRdpEvents -Start $queryStart -End $End
    }

    $primary = Get-LsmSessions `
        -QueryStart $queryStart `
        -RangeStart $Start `
        -RangeEnd $End `
        -RcmEvents $rcm `
        -SecurityEvents $security

    if (@($primary).Count -gt 0) {
        $merged = @($primary)
    }
    else {
        # Old/misconfigured servers sometimes have no useful LSM history.
        # In that case Security becomes an automatic fallback even in fast mode.
        if (-not $UseSecurity) {
            $security = Get-SecurityRdpEvents -Start $queryStart -End $End
        }

        $fallback = Get-SecurityFallbackSessions `
            -SecurityEvents $security `
            -RangeEnd $End

        $merged = @($fallback)
    }

    $results = New-Object System.Collections.ArrayList

    foreach ($s in $merged) {
        if (Test-SessionIntersectsRange -Session $s -RangeStart $Start -RangeEnd $End) {
            [void]$results.Add(
                (Convert-SessionToResult -Session $s -RangeStart $Start -RangeEnd $End)
            )
        }
    }

    return @($results | Sort-Object _Start -Descending)
}

# ---------------------------------------------------------------------------
# Локалізація / представлення
# ---------------------------------------------------------------------------

function Get-ScopeUa {
    param([string]$Scope)

    switch ($Scope) {
        'Local'         { return 'Локальний' }
        'Domain'        { return 'Доменний' }
        'Local/Unknown' { return 'Локальний/невідомо' }
        default         { return 'Невідомо' }
    }
}

function Get-StateUa {
    param([string]$State)

    switch ($State) {
        'Active'                   { return 'Активний' }
        'Disconnected'             { return 'Відʼєднаний' }
        'Logged off'               { return 'Завершений' }
        'Open / unknown'           { return 'Відкритий / невідомо' }
        'Closed by new session ID' { return 'Закрито при повторному ID' }
        default                    { return $State }
    }
}

function Get-ClosureUa {
    param([string]$Closure)

    switch -Wildcard ($Closure) {
        'LOGOFF (proper)'                    { return 'Коректний вихід із системи' }
        'DISCONNECT / session left open'     { return 'Відʼєднано, сеанс залишено' }
        'ACTIVE / still open'                { return 'Активний, сеанс відкритий' }
        'INCOMPLETE / SessionId reused'      { return 'Неповні дані: ID використано повторно' }
        'TERMINATED (cause unknown)'         { return 'Сеанс завершено, причина невідома' }
        'OPEN / no logoff event'             { return 'Відкритий / немає події виходу' }
        default                              { return $Closure }
    }
}

function Get-DetailUa {
    param([string]$Detail)

    if ([string]::IsNullOrWhiteSpace($Detail)) {
        return ''
    }

    switch -Wildcard ($Detail) {
        'LSM 23:*' {
            return 'LSM 23: зафіксовано коректний вихід із системи'
        }
        'No logoff/disconnect before selected End' {
            return 'До кінця вибраного періоду не було події виходу або відʼєднання'
        }
        'Disconnected by another session/admin' {
            return 'Сеанс відʼєднано іншою сесією або адміністратором'
        }
        'Explicit Disconnect was recorded*' {
            return 'Зафіксовано явну команду Disconnect (LSM 39)'
        }
        'Disconnected without Log off*' {
            return 'Відʼєднання без Log off. Сервер не завжди може відрізнити закриття RDP хрестиком від втрати мережі або аварії клієнта'
        }
        'Security 4647:*' {
            return 'Security 4647: користувач ініціював вихід із системи'
        }
        'Security 4634 without matching 4647' {
            return 'Security 4634 без відповідної 4647: сеанс завершено, точна причина не визначена'
        }
        'New LSM 21 appeared*' {
            return 'Зʼявилася нова подія LSM 21 з тим самим Session ID до видимого LSM 23; частина історії втрачена'
        }
        '0: no additional info / client connection ended' {
            return 'Код 0: додаткової інформації немає; клієнтське зʼєднання завершилося'
        }
        '5: connection replaced by another connection' {
            return 'Код 5: зʼєднання замінено іншим зʼєднанням'
        }
        '11: user initiated disconnect' {
            return 'Код 11: користувач ініціював відʼєднання'
        }
        default {
            return $Detail
        }
    }
}

function Get-QualityUa {
    param([string]$Quality)

    switch ($Quality) {
        'Complete'            { return 'Повні' }
        'Partial start'       { return 'Немає початку' }
        'Open at range end'   { return 'Відкритий на кінець періоду' }
        'Partial start + end' { return 'Неповні: початок і кінець' }
        default               { return $Quality }
    }
}

function Get-SourceUa {
    param([string]$Source)

    switch ($Source) {
        'LSM'               { return 'TerminalServices LSM' }
        'LSM partial'       { return 'TerminalServices LSM (частково)' }
        'Security fallback' { return 'Security (резервний режим)' }
        default             { return $Source }
    }
}

function Get-StartedUa {
    param($Row)

    if ($Row.Started -eq 'before available history') {
        return 'До доступної історії'
    }

    return [string]$Row.Started
}

function Get-EndedUa {
    param($Row)

    if ([string]::IsNullOrWhiteSpace([string]$Row.Ended)) {
        return '—'
    }

    return [string]$Row.Ended
}

# ---------------------------------------------------------------------------
# Export
# ---------------------------------------------------------------------------

function ConvertTo-HtmlEncoded {
    param([object]$Value)

    if ($null -eq $Value) {
        return ''
    }

    $s = [string]$Value
    $s = $s.Replace('&', '&amp;')
    $s = $s.Replace('<', '&lt;')
    $s = $s.Replace('>', '&gt;')
    $s = $s.Replace('"', '&quot;')
    return $s
}

function Export-RdpHtml {
    param(
        [object[]]$Rows,
        [datetime]$Start,
        [datetime]$End,
        [string]$Path
    )

    $proper = @($Rows | Where-Object { $_.Category -eq 'Proper logoff' }).Count
    $disconnected = @($Rows | Where-Object { $_.Category -eq 'Disconnected/open' }).Count
    $active = @($Rows | Where-Object { $_.Category -eq 'Active/open' }).Count
    $incomplete = @($Rows | Where-Object { $_.Category -eq 'Incomplete/unknown' }).Count

    $mainRows = ''
    $detailRows = ''

    foreach ($r in $Rows) {
        $class = ''

        if ($r.Category -eq 'Proper logoff') { $class = 'ok' }
        elseif ($r.Category -eq 'Disconnected/open') { $class = 'bad' }
        elseif ($r.Category -eq 'Active/open') { $class = 'active' }
        elseif ($r.Category -eq 'Incomplete/unknown') { $class = 'warn' }

        $dr = "$(ConvertTo-HtmlEncoded $r.Disconnects) / $(ConvertTo-HtmlEncoded $r.Reconnects)"

        $mainRows += @"
<tr class="$class">
<td>$(ConvertTo-HtmlEncoded $r.Account)</td>
<td>$(ConvertTo-HtmlEncoded (Get-ScopeUa $r.Scope))</td>
<td class="center">$(ConvertTo-HtmlEncoded $r.SessionId)</td>
<td>$(ConvertTo-HtmlEncoded (Get-StartedUa $r))</td>
<td>$(ConvertTo-HtmlEncoded (Get-EndedUa $r))</td>
<td class="nowrap">$(ConvertTo-HtmlEncoded $r.Lifetime)</td>
<td class="nowrap">$(ConvertTo-HtmlEncoded $r.ConnectedTime)</td>
<td class="nowrap">$(ConvertTo-HtmlEncoded $r.DisconnectedTime)</td>
<td>$(ConvertTo-HtmlEncoded (Get-ClosureUa $r.Closure))</td>
<td class="center nowrap">$dr</td>
<td class="ip">$(ConvertTo-HtmlEncoded $r.IPs)</td>
</tr>
"@

        $detailRows += @"
<tr class="$class">
<td>$(ConvertTo-HtmlEncoded $r.Account)</td>
<td>$(ConvertTo-HtmlEncoded $r.ClientNames)</td>
<td>$(ConvertTo-HtmlEncoded (Get-DetailUa $r.ClosureDetail))</td>
<td>$(ConvertTo-HtmlEncoded (Get-QualityUa $r.DataQuality))</td>
<td>$(ConvertTo-HtmlEncoded (Get-SourceUa $r.Source))</td>
<td>$(ConvertTo-HtmlEncoded $r.Events)</td>
</tr>
"@
    }

    $html = @"
