</style>
</head>
<body>
<div class="page">

<h1>Аудит RDP-сесій</h1>
<div class="meta">
Сервер: <b>$(ConvertTo-HtmlEncoded $env:COMPUTERNAME)</b><br>
Період: <b>$($Start.ToString('dd.MM.yyyy HH:mm'))</b> — <b>$($End.ToString('dd.MM.yyyy HH:mm'))</b><br>
Сформовано: $(Get-Date -Format 'dd.MM.yyyy HH:mm:ss')
</div>

<table class="summary">
<tr>
<td><span class="n">$($Rows.Count)</span>Усього сесій</td>
<td><span class="n">$proper</span>Коректний вихід</td>
<td><span class="n">$disconnected</span>Відʼєднано / залишено</td>
<td><span class="n">$active</span>Активні / відкриті</td>
<td><span class="n">$incomplete</span>Неповні дані</td>
</tr>
</table>

<div class="legend">
<b>Позначення:</b>
<span class="dot green first"></span>коректний Log off;
<span class="dot red"></span>Disconnect без Log off;
<span class="dot blue"></span>сеанс відкритий на кінець періоду;
<span class="dot yellow"></span>неповна історія.
<br>
Disconnect означає, що Windows-сеанс залишився на сервері. Це часто буває при закритті RDP хрестиком,
але так само може статися через втрату мережі, VPN або аварію клієнта.
</div>

<h2>Сесії</h2>
<div class="tablebox">
<table class="audit main">
<colgroup>
<col class="c-user"><col class="c-type"><col class="c-id"><col class="c-start"><col class="c-end">
<col class="c-life"><col class="c-con"><col class="c-dis"><col class="c-result"><col class="c-dr"><col class="c-ip">
</colgroup>
<thead>
<tr>
<th>Користувач</th>
<th>Тип</th>
<th>ID</th>
<th>Початок</th>
<th>Завершення</th>
<th>Тривалість</th>
<th>Підключено</th>
<th>Відʼєднано</th>
<th>Результат</th>
<th>D / R</th>
<th>IP-адреси</th>
</tr>
</thead>
<tbody>
$mainRows
</tbody>
</table>
</div>

<h2>Технічні деталі</h2>
<div class="tablebox">
<table class="audit tech">
<colgroup>
<col class="c-user"><col class="c-client"><col class="c-details"><col class="c-quality"><col class="c-source"><col class="c-events">
</colgroup>
<thead>
<tr>
<th>Користувач</th>
<th>Імʼя клієнта</th>
<th>Деталі</th>
<th>Якість даних</th>
<th>Джерело</th>
<th>Event ID</th>
</tr>
</thead>
<tbody>
$detailRows
</tbody>
</table>
</div>

<h2>Що означають поля</h2>
<table class="fields">
<tr><th>Користувач / Тип</th><td>Локальний або доменний обліковий запис, для якого реконструйовано RDP-сеанс.</td></tr>
<tr><th>ID</th><td>Windows Session ID. Після завершення старої сесії цей номер може бути використаний повторно.</td></tr>
<tr><th>Початок / Завершення</th><td>Час створення та повного закриття логічної Windows-сесії. «До доступної історії» означає, що початок уже стертий із журналу.</td></tr>
<tr><th>Тривалість</th><td>Час існування сесії. Позначка &gt;= означає «щонайменше»: точний початок уже відсутній.</td></tr>
<tr><th>Підключено</th><td>Сумарний відомий час, коли RDP-клієнт був реально приєднаний до сесії.</td></tr>
<tr><th>Відʼєднано</th><td>Час, коли Windows-сеанс продовжував існувати на сервері без активного RDP-підключення.</td></tr>
<tr><th>D / R</th><td>Кількість Disconnect / Reconnect усередині однієї логічної сесії.</td></tr>
<tr><th>IP-адреси</th><td>Адреси джерела, які сервер бачив під час входу або перепідключення. При VPN/NAT це може бути адреса після проходження VPN/NAT.</td></tr>
<tr><th>Імʼя клієнта</th><td>Імʼя віддаленого ПК, якщо воно збереглося у журналах Windows.</td></tr>
<tr><th>Якість даних</th><td>Чи вистачає журналів для повної реконструкції. Очищені або перезаписані журнали дають неповні записи.</td></tr>
</table>

<div class="foot">
Основні джерела: TerminalServices-LocalSessionManager (21/23/24/25/39/40),
TerminalServices-RemoteConnectionManager (1149), Security
(4624 LogonType 10, 4634, 4647, 4778, 4779).
</div>

</div>
</body>
</html>
"@

    [System.IO.File]::WriteAllText(
        $Path,
        $html,
        (New-Object System.Text.UTF8Encoding($true))
    )
}

function Get-CsvRowsUa {
    param([object[]]$Rows)

    foreach ($r in $Rows) {
        [pscustomobject]@{
            'Користувач' = $r.Account
            'Тип облікового запису' = (Get-ScopeUa $r.Scope)
            'Session ID' = $r.SessionId
            'Початок' = (Get-StartedUa $r)
            'Завершення' = (Get-EndedUa $r)
            'Тривалість' = $r.Lifetime
            'Підключено' = $r.ConnectedTime
            'Відʼєднано' = $r.DisconnectedTime
            'Стан' = (Get-StateUa $r.FinalState)
            'Результат' = (Get-ClosureUa $r.Closure)
            'Деталі' = (Get-DetailUa $r.ClosureDetail)
            'Кількість відʼєднань' = $r.Disconnects
            'Кількість перепідключень' = $r.Reconnects
            'IP-адреси' = $r.IPs
            'Останній IP' = $r.LastIP
            'Імена клієнтів' = $r.ClientNames
            'Автентифікація' = $r.Auth
            'Якість даних' = (Get-QualityUa $r.DataQuality)
            'Джерело' = (Get-SourceUa $r.Source)
            'Події' = $r.Events
        }
    }
}

