    @{ Name='ConnectedTime';    Header='Підключено';     Width=100; Tip='Сумарний відомий час активного RDP-підключення.' },
    @{ Name='DisconnectedTime'; Header='Відʼєднано';     Width=100; Tip='Час існування Windows-сеансу без активного RDP-клієнта.' },
    @{ Name='Closure';          Header='Результат';      Width=205; Tip='Log off, Disconnect, активна або неповна сесія.' },
    @{ Name='Disconnects';      Header='Disc.';          Width=62;  Tip='Кількість Disconnect.' },
