)

function Initialize-GridColumns {
    $grid.Columns.Clear()

    foreach ($def in $script:GridColumnDefs) {
        $col = New-Object System.Windows.Forms.DataGridViewTextBoxColumn
        $col.Name = $def.Name
        $col.HeaderText = $def.Header
        $col.Width = [int]$def.Width
        $col.HeaderCell.ToolTipText = $def.Tip
        $col.SortMode = 'Automatic'

        if ($def.Name -in @('Disconnects','Reconnects','SessionId')) {
            $col.DefaultCellStyle.Alignment = 'MiddleCenter'
            $col.HeaderCell.Style.Alignment = 'MiddleCenter'
        }

        if ($def.Name -eq 'Account') {
            $col.Frozen = $true
        }

        [void]$grid.Columns.Add($col)
    }
}

Initialize-GridColumns

function Get-GridValue {
    param(
        $Row,
        [string]$Name
    )

    switch ($Name) {
        'Account'          { return $Row.Account }
        'Scope'            { return (Get-ScopeUa $Row.Scope) }
        'SessionId'        { return $Row.SessionId }
        'Started'          { return (Get-StartedUa $Row) }
        'Ended'            { return (Get-EndedUa $Row) }
        'Lifetime'         { return $Row.Lifetime }
        'ConnectedTime'    { return $Row.ConnectedTime }
        'DisconnectedTime' { return $Row.DisconnectedTime }
        'Closure'          { return (Get-ClosureUa $Row.Closure) }
        'Disconnects'      { return $Row.Disconnects }
        'Reconnects'       { return $Row.Reconnects }
        'IPs'              { return $Row.IPs }
        'ClientNames'      { return $Row.ClientNames }
        default            { return '' }
    }
}

function Get-SelectedFilterCategory {
    switch ([string]$cmbFilter.SelectedItem) {
        'Коректний вихід'             { return 'Proper logoff' }
        'Відʼєднано / сеанс залишено' { return 'Disconnected/open' }
        'Активні / відкриті'          { return 'Active/open' }
        'Неповні / невідомі'          { return 'Incomplete/unknown' }
        default                        { return 'All' }
    }
}

function Refresh-Grid {
    $search = $txtSearch.Text.Trim().ToLowerInvariant()
    $filter = Get-SelectedFilterCategory

    $rows = @($script:Results)

    if ($filter -ne 'All') {
        $rows = @($rows | Where-Object { $_.Category -eq $filter })
    }

    if ($search) {
        $rows = @(
            $rows | Where-Object {
                (
                    $_.Account + ' ' +
                    $_.IPs + ' ' +
                    $_.ClientNames + ' ' +
                    (Get-ClosureUa $_.Closure) + ' ' +
                    (Get-DetailUa $_.ClosureDetail) + ' ' +
                    $_.SessionId
                ).ToLowerInvariant().Contains($search)
            }
        )
    }

    $script:FilteredResults = @($rows)

    $grid.SuspendLayout()
    try {
        $grid.Rows.Clear()

        foreach ($r in $rows) {
            $idx = $grid.Rows.Add()
            $gr = $grid.Rows[$idx]
            $gr.Tag = $r

            for ($i = 0; $i -lt $script:GridColumnDefs.Count; $i++) {
                $name = $script:GridColumnDefs[$i].Name
                $gr.Cells[$i].Value = [string](Get-GridValue -Row $r -Name $name)
            }

            if ($r.Category -eq 'Proper logoff') {
                $gr.DefaultCellStyle.BackColor = [System.Drawing.Color]::FromArgb(226,244,231)
            }
            elseif ($r.Category -eq 'Disconnected/open') {
                $gr.DefaultCellStyle.BackColor = [System.Drawing.Color]::FromArgb(252,226,226)
            }
            elseif ($r.Category -eq 'Active/open') {
                $gr.DefaultCellStyle.BackColor = [System.Drawing.Color]::FromArgb(226,238,251)
            }
            elseif ($r.Category -eq 'Incomplete/unknown') {
                $gr.DefaultCellStyle.BackColor = [System.Drawing.Color]::FromArgb(250,243,213)
            }

            $gr.DefaultCellStyle.WrapMode = 'False'
        }
    }
    finally {
        $grid.ResumeLayout()
    }

    $proper = @($script:Results | Where-Object { $_.Category -eq 'Proper logoff' }).Count
    $disc = @($script:Results | Where-Object { $_.Category -eq 'Disconnected/open' }).Count
    $active = @($script:Results | Where-Object { $_.Category -eq 'Active/open' }).Count
    $inc = @($script:Results | Where-Object { $_.Category -eq 'Incomplete/unknown' }).Count

    $lblSummary.Text = "Сесій: $($script:Results.Count)   |   Log off: $proper   |   Залишено: $disc   |   Активні: $active   |   Неповні: $inc   |   Показано: $($rows.Count)"
}


