function Show-RowDetails {
    param($Row)

    if ($null -eq $Row) {
        return
    }

    $message = @"
Користувач:       $($Row.Account)
Тип:              $(Get-ScopeUa $Row.Scope)
Session ID:       $($Row.SessionId)

Початок:          $(Get-StartedUa $Row)
Завершення:       $(Get-EndedUa $Row)
Тривалість:       $($Row.Lifetime)
Підключено:       $($Row.ConnectedTime)
Відʼєднано:       $($Row.DisconnectedTime)

Стан:             $(Get-StateUa $Row.FinalState)
Результат:        $(Get-ClosureUa $Row.Closure)
Disconnect:       $($Row.Disconnects)
Reconnect:        $($Row.Reconnects)

IP:               $($Row.IPs)
Останній IP:      $($Row.LastIP)
Клієнти:          $($Row.ClientNames)
Автентифікація:   $($Row.Auth)

Якість даних:     $(Get-QualityUa $Row.DataQuality)
Джерело:          $(Get-SourceUa $Row.Source)
Події:            $($Row.Events)

Деталі:
$(Get-DetailUa $Row.ClosureDetail)
"@

    [System.Windows.Forms.MessageBox]::Show(
        $message,
        'Деталі RDP-сесії',
        [System.Windows.Forms.MessageBoxButtons]::OK,
        [System.Windows.Forms.MessageBoxIcon]::Information
    ) | Out-Null
}

$grid.add_CellDoubleClick({
    param($sender, $e)

    if ($e.RowIndex -ge 0) {
        $row = $grid.Rows[$e.RowIndex].Tag
        Show-RowDetails -Row $row
    }
})

$btnAdvanced.add_Click({
    Show-AdvancedOptions
})

$btnHelp.add_Click({
    Show-HelpWindow
})

$btnAbout.add_Click({
    Show-AboutWindow
})

$btnAnalyze.add_Click({
    try {
        $btnAnalyze.Enabled = $false
        $btnCsv.Enabled = $false
        $btnHtml.Enabled = $false
        $form.Cursor = [System.Windows.Forms.Cursors]::WaitCursor

        $start = $dtStart.Value
        $end = $dtEnd.Value
        $lookback = [int]$script:OptionLookbackDays
        $useSecurity = [bool]$script:OptionUseSecurity
        $sw = [System.Diagnostics.Stopwatch]::StartNew()

        $modeText = if ($useSecurity) { 'розширений Security' } else { 'швидкий режим' }
        $statusLabel.Text = "Читаю RDP-журнали ($modeText): $($start.ToString('dd.MM.yyyy HH:mm')) — $($end.ToString('dd.MM.yyyy HH:mm'))..."
        [System.Windows.Forms.Application]::DoEvents()

        $script:Results = Invoke-RdpAudit `
            -Start $start `
            -End $end `
            -LookbackDays $lookback `
            -UseSecurity $useSecurity
        $script:LastStart = $start
        $script:LastEnd = $end

        Refresh-Grid

        $btnCsv.Enabled = ($script:Results.Count -gt 0)
        $btnHtml.Enabled = ($script:Results.Count -gt 0)

        $sw.Stop()
        $statusLabel.Text = "Готово за $([math]::Round($sw.Elapsed.TotalSeconds,1)) с. Сесій: $($script:Results.Count). Подвійний клік по рядку — повні деталі."
    }
    catch {
        [System.Windows.Forms.MessageBox]::Show(
            "Помилка аналізу:`r`n$($_.Exception.Message)`r`n`r`nРядок: $($_.InvocationInfo.ScriptLineNumber)`r`nКоманда: $($_.InvocationInfo.Line)",
            'RDP Аудит сесій',
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Error
        ) | Out-Null

        $statusLabel.Text = 'Помилка аналізу.'
    }
    finally {
        $btnAnalyze.Enabled = $true
        $form.Cursor = [System.Windows.Forms.Cursors]::Default
    }
})

$txtSearch.add_TextChanged({
    if ($script:Results.Count -gt 0) {
        Refresh-Grid
    }
})

$cmbFilter.add_SelectedIndexChanged({
    if ($script:Results.Count -gt 0) {
        Refresh-Grid
    }
})

$btnCsv.add_Click({
    if ($script:Results.Count -eq 0) {
        return
    }

    $dialog = New-Object System.Windows.Forms.SaveFileDialog
    $dialog.Filter = 'CSV (*.csv)|*.csv|Усі файли (*.*)|*.*'
    $serverSafe = ($env:COMPUTERNAME -replace '[^A-Za-z0-9_.-]','_')
    $dialog.FileName = "RDP_Audit_${serverSafe}_$($script:LastStart.ToString('yyyy-MM-dd'))_$($script:LastEnd.ToString('yyyy-MM-dd')).csv"

    if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        try {
            Get-CsvRowsUa -Rows $script:FilteredResults |
                Export-Csv -Path $dialog.FileName -NoTypeInformation -Encoding UTF8

            $statusLabel.Text = "CSV збережено: $($dialog.FileName)"
        }
        catch {
            [System.Windows.Forms.MessageBox]::Show($_.Exception.Message,'Помилка експорту CSV') | Out-Null
        }
    }
})

$btnHtml.add_Click({
    if ($script:Results.Count -eq 0) {
        return
    }

    $dialog = New-Object System.Windows.Forms.SaveFileDialog
    $dialog.Filter = 'HTML (*.html)|*.html|Усі файли (*.*)|*.*'
    $serverSafe = ($env:COMPUTERNAME -replace '[^A-Za-z0-9_.-]','_')
    $dialog.FileName = "RDP_Audit_${serverSafe}_$($script:LastStart.ToString('yyyy-MM-dd'))_$($script:LastEnd.ToString('yyyy-MM-dd')).html"

    if ($dialog.ShowDialog() -eq [System.Windows.Forms.DialogResult]::OK) {
        try {
            Export-RdpHtml `
                -Rows $script:FilteredResults `
                -Start $script:LastStart `
                -End $script:LastEnd `
                -Path $dialog.FileName

            $statusLabel.Text = "HTML збережено: $($dialog.FileName)"
        }
        catch {
            [System.Windows.Forms.MessageBox]::Show($_.Exception.Message,'Помилка експорту HTML') | Out-Null
        }
    }
})

$form.add_Shown({
    $form.Activate()

    if (-not (Test-IsAdministrator)) {
        [System.Windows.Forms.MessageBox]::Show(
            "Рекомендовано запускати програму від адміністратора.`r`n`r`nБез підвищених прав TerminalServices-журнали програма все одно спробує прочитати, але Security може бути недоступним.",
            'RDP Аудит сесій',
            [System.Windows.Forms.MessageBoxButtons]::OK,
            [System.Windows.Forms.MessageBoxIcon]::Information
        ) | Out-Null
    }
})

[void]$form.ShowDialog()
